#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    vector<string> g(n);
    for (int i = 0; i < n; i++) {
        string s;
        cin >> s;
        if ((int)s.size() < m) s.resize(m, '.');
        else if ((int)s.size() > m) s.resize(m);
        g[i] = s;
    }

    queue<pair<int,int> > q;
    for (int j = 0; j < m; j++)
        if (g[0][j] == 'o') q.push(make_pair(0, j));

    while (!q.empty()) {
        int i = q.front().first;
        int j = q.front().second;
        q.pop();

        if (i + 1 >= n) continue;

        if (g[i + 1][j] == '.') {
            // regra 1: escorre verticalmente para baixo
            g[i + 1][j] = 'o';
            q.push(make_pair(i + 1, j));
        } else if (g[i + 1][j] == '#') {
            // apoiado sobre prateleira: escorre para os dois lados
            if (j > 0 && g[i][j - 1] == '.') {
                g[i][j - 1] = 'o';
                q.push(make_pair(i, j - 1));
            }
            if (j + 1 < m && g[i][j + 1] == '.') {
                g[i][j + 1] = 'o';
                q.push(make_pair(i, j + 1));
            }
        }
    }

    for (int i = 0; i < n; i++)
        cout << g[i] << "\n";

    return 0;
}
